 const applied=cleanFilters(filters),rows=await fetchRows(db,id,applied,identity),totals={rows:rows.length};if(rows.length>=5000){totals.resultLimit=5000;totals.mayBeTruncated=true;}
 for(const key of REPORT_MEASURES[id]||[])totals[key]=rows.reduce((sum,row)=>sum+(typeof row[key]==="number"?row[key]:Number(row[key]||0)),0);
 if(id==="payment-reconciliation"){
  const a=[applied.from||null,applied.to||null,applied.status,applied.q];
  const sums=(await db.query("select pt.currency,coalesce(sum(pt.amount) filter(where pt.status='succeeded'),0)::numeric approved,coalesce(sum(pt.amount) filter(where pt.status='failed'),0)::numeric failed,coalesce(sum(pt.amount) filter(where pt.status='refunded'),0)::numeric refunded,coalesce(sum(pt.amount) filter(where pt.status in ('initiated','pending')),0)::numeric pending,coalesce(sum(pt.amount) filter(where pt.status='cancelled'),0)::numeric cancelled from payment_transaction pt join membership_application_payment ap on ap.payment_transaction_id=pt.id where ($1::date is null or coalesce(pt.verified_at,pt.completed_at,pt.created_at) >= $1::date) and ($2::date is null or coalesce(pt.verified_at,pt.completed_at,pt.created_at) < ($2::date + interval '1 day')) and ($3='' or pt.status=$3) and ($4='' or lower(coalesce(pt.purpose_reference,'')||' '||pt.id::text) like lower('%'||$4||'%')) group by pt.currency order by pt.currency",a)).rows;
  totals.amountsByCurrency=sums.length?sums.map(row=>String(row.currency)+": approved "+Number(row.approved).toFixed(2)+", failed "+Number(row.failed).toFixed(2)+", refunded/reversed "+Number(row.refunded).toFixed(2)+", pending "+Number(row.pending).toFixed(2)+", cancelled "+Number(row.cancelled).toFixed(2)).join("; "):"No matching membership payments";
 }
