function pdfText(s){return String(s??"").normalize("NFKD").replace(/[^\x20-\x7E]/g," ").replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)");}
function wrapPdfLine(value,width=105){
 const words=String(value??"").replace(/\s+/g," ").trim().split(" "),out=[];let line="";
 for(const word of words){if(!word)continue;const parts=word.length>width?(word.match(new RegExp(".{1,"+width+"}","g"))||[word]):[word];for(const part of parts){if(line&&line.length+1+part.length>width){out.push(line);line=part;}else line=line?line+" "+part:part;}}
 if(line||!out.length)out.push(line);return out;
}

function startsWithFormulaPrefix(raw){
 let index=0;
 while(index<raw.length&&raw.charCodeAt(index)<=0x20)index+=1;
 const first=raw[index];
 return first!==undefined&&"=+-@".includes(first);
}
function csvCell(value){
 const raw=value instanceof Date?value.toISOString():String(value??"");
 const safe=typeof value==="string"&&startsWithFormulaPrefix(raw)?"'"+raw:raw;
 return '"'+safe.replace(/"/g,'""')+'"';
}
