 const objs=[];const add=x=>(objs.push(x),objs.length),font=add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"),pageIds=[];
 pages.forEach((page,pageIndex)=>{let stream="BT /F1 9 Tf 42 800 Td 12 TL ";page.forEach((line,i)=>{stream+=`${i?" T* ":""}(${pdfText(line)}) Tj `;});stream+=` T* (${pdfText("Page "+(pageIndex+1)+" of "+pages.length)}) Tj ET`;const content=add(`<< /Length ${Buffer.byteLength(stream,"ascii")} >>\nstream\n${stream}\nendstream`),pid=add(`<< /Type /Page /Parent PARENT 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${content} 0 R >>`);pageIds.push(pid);});
 const pagesId=add(`<< /Type /Pages /Kids [${pageIds.map(n=>n+" 0 R").join(" ")}] /Count ${pages.length} >>`);for(const pid of pageIds)objs[pid-1]=objs[pid-1].replace("PARENT",String(pagesId));const catalog=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);
 let out="%PDF-1.4\n",offsets=[0];for(let i=0;i<objs.length;i++){offsets.push(Buffer.byteLength(out,"ascii"));out+=`${i+1} 0 obj\n${objs[i]}\nendobj\n`;}
